import sqlite3
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Optional

from langchain_core.tools import tool

DB_PATH = "recruiting.db"

_STAGE_ORDER = ["applied", "phone_screen", "onsite", "offer", "hired"]


@dataclass
class StageChangeResult:
    applicant_id: int
    requisition_id: str
    previous_stage: Optional[str]
    new_stage: str
    changed: bool
    message: str


def _is_allowed(current: str, target: str) -> bool:
    if target == "rejected":
        return current not in ("hired", "rejected")
    if current not in _STAGE_ORDER or target not in _STAGE_ORDER:
        return False
    return _STAGE_ORDER.index(target) == _STAGE_ORDER.index(current) + 1


@tool
def advance_applicant_stage(applicant_id: int, requisition_id: str, new_stage: str, note: Optional[str] = None) -> StageChangeResult:
    """Advance an applicant to the next pipeline stage."""
    target = new_stage.strip().lower()
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT stage FROM applications WHERE applicant_id = ? AND requisition_id = ?",
            (applicant_id, requisition_id),
        ).fetchone()
        if row is None:
            return StageChangeResult(applicant_id, requisition_id, None, target, False, "No application found for this applicant and requisition.")
        current = row[0]
        if current == target:
            return StageChangeResult(applicant_id, requisition_id, current, target, False, "Applicant is already in this stage.")
        if not _is_allowed(current, target):
            return StageChangeResult(applicant_id, requisition_id, current, target, False, f"Transition from {current} to {target} is not permitted.")
        now = datetime.now(timezone.utc).isoformat()
        with conn:
            conn.execute(
                "UPDATE applications SET stage = ?, updated_at = ? WHERE applicant_id = ? AND requisition_id = ?",
                (target, now, applicant_id, requisition_id),
            )
            conn.execute(
                "INSERT INTO stage_history (applicant_id, requisition_id, from_stage, to_stage, note, changed_at) VALUES (?, ?, ?, ?, ?, ?)",
                (applicant_id, requisition_id, current, target, note, now),
            )
        return StageChangeResult(applicant_id, requisition_id, current, target, True, f"Moved from {current} to {target}.")
    finally:
        conn.close()

from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP
from ats_client import ats

mcp = FastMCP("recruiting")


@dataclass
class AccessGrant:
    requisition_id: str
    user_id: str
    role: str
    granted: bool


@mcp.tool()
def grant_requisition_reviewer_access(requisition_id: str, user_id: str) -> AccessGrant:
    req = ats.requisitions.get(requisition_id)
    if req is None or req["status"] == "closed":
        return AccessGrant(requisition_id, user_id, "reviewer", False)
    ats.requisitions.add_collaborator(requisition_id, user_id=user_id, role="reviewer")
    return AccessGrant(requisition_id, user_id, "reviewer", True)
